  2441                  x->obj = PDF_NULL;
  2442          }
  2443          else if (x->type == 'n')
  2444          {
  2445                  fz_seek(ctx, doc->file, x->ofs, SEEK_SET);
  2446
  2447                  fz_try(ctx)
  2448                  {
